"""All Command Building operations in this class"""
from builtins import object
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.connection_manager.communicator import Communicator

# from taf.ul.trs_e2e_fw.lib.ipsec.ipsec_validate import ipsec_validate



class CommandBuilder(object):
    """All Command Building operations in this class"""

    def __init__(self):
        # self.config = ConfigHandler.get_config()
        # self.ipsec_val_obj = ipsec_validate()
        self.TMP_IPSEC_CONF_FILE = 'tmp_ipsec.conf'
        self.BACKUP_IPSEC_CONF_FILE = '/usr/local/etc/backup.conf'
        self.comunicator_obj = Communicator()

    def build_append_command_template(self):
        """Returns part of sed command template to append"""
        return self._build_command(r" a\       {param}={val}'")

    def build_comment_command_template(self):
        """Returns part of sed command template to comment"""
        return self._build_command(r",/^\s*$/s/^(\s*)({param}=.*)/\\1#\\2/'")

    def build_uncomment_command_template(self):
        """Returns part of sed command template to uncomment"""
        return self._build_command(r",/^\s*$/s/^(\s*)#({param}=.*)/\\1\\2/'")

    def build_replace_command_template(self):
        """Returns part of sed command template to replace"""
        return self._build_command(r",/^\s*$/s/(^\s*{param}=).*/\\1{val}/'")

    def build_awk_command_template(self):
        """Build awk command template"""
        """Returns awk command template"""
        return r"awk '/^\s*conn {conn_num}/{{p=1;print;next}} p&&/^\s*$/{{p=0}};p' {conf_file}" \
               " | grep {param} | wc -l"

    def build_awk_command_for_all_connections(self):
        """Build awk command for all connections"""
        return r"awk '/^\s*conn/{{p=1;print;next}} p&&/^\s*$/{{p=0}};p'  {conf_file} | grep 'conn'"

    def build_awk_command_to_get_params(self):
        """Build awk command to get params"""
        return r"awk '/^\s*conn {conn_num}/{{p=1;print;next}} p&&/^\s*$/{{p=0}};p' {conf_file} " \
               r"| grep {param}="

    def _build_sed_command(self, conn, param_name, new_value):
        param_name, new_value = self._escape_special_chars(param_name, new_value)
        command_template = self._get_command_template(conn, param_name, new_value)
        ipsec_conf_path = get_config_variable(['ipsec_conf_path'])
        command = command_template.format(conn_num=conn, param=param_name, val=new_value,
                                          conf_file=ipsec_conf_path,
                                          tmpfile=self.TMP_IPSEC_CONF_FILE)
        return command

    def _build_command(self, cmd_segment):
        cmd = self._build_base_cmd()
        cmd += cmd_segment
        cmd += self._build_redirect_command()
        return cmd

    def _build_base_cmd(self):
        return "sed -r '/^conn {conn_num}/"

    def _build_redirect_command(self):
        return " {conf_file} > {tmpfile}"

    def _escape_special_chars(self, param_name, new_value):
        param_name = param_name.replace('/', r'\/')
        new_value = new_value.replace('/', r'\/')
        return param_name, new_value

    def _get_command_template(self, conn, param_name, new_value):
        if self._check_if_param_is_new(conn, param_name):
            return self.build_append_command_template()
        elif new_value.strip().lower() == 'comment':
            return self.build_comment_command_template()
        elif new_value.strip().lower() == 'uncomment':
            return self.build_uncomment_command_template()
        else:
            return self.build_replace_command_template()

    def _check_if_param_is_new(self, conn, param_name):
        awkcommand_template = self.build_awk_command_template()
        ipsec_conf_path = get_config_variable(["ipsec_conf_path"])
        ip = get_config_variable(["secure_gw", "ip"])
        user = get_config_variable(["secure_gw", "user"])
        password = get_config_variable(["secure_gw", "password"])
        awkcommand = awkcommand_template.format(conn_num=conn, param=param_name,
                                                conf_file=ipsec_conf_path)
        result = self.comunicator_obj.execute_command_remotely_and_verify(ip, user, password,
                                                                          awkcommand)
        if int(result) > 0:
            return False
        return True
